def is_good(n, memo):
    if n in memo:
        return memo[n]

    s = str(n)
    if len(s) == 1:
        memo[n] = True
        return True

    # Check if digits are distinct and nonzero
    digits = [int(d) for d in s]
    if len(set(digits)) != len(digits) or 0 in digits:
        memo[n] = False
        return False

    # Check if removing one digit gives a good divisor
    for i in range(len(s)):
        d_str = s[:i] + s[i+1:]
        if d_str == "": continue
        d = int(d_str)
        if n % d == 0:
            if is_good(d, memo):
                memo[n] = True
                return True

    memo[n] = False
    return False

